1	// Package chainledger graph structure rules shared by every graph reader.
2	//
3	// Both on-disk graph files (UnmarshalGraphFile) and the graph embedded in a
4	// snapshot (ParseSnapshot) describe the same thing: a set of dataset names and
5	// each dataset's direct upstreams. The rules below are the single authority for
6	// turning that description into the validated, normalized adjacency both
7	// readers build on, so the two file formats can never disagree about whether
8	// one graph is legal or about which lineage relations it expresses:
9	//
10	//   - an empty dataset name is rejected;
11	//   - a dataset declared more than once is rejected;
12	//   - an upstream that is not itself a declared dataset is rejected, with the
13	//     referrer and the referenced name both in the error;
14	//   - a direct self-dependency or any indirect dependency cycle is rejected,
15	//     with the datasets on the cycle named;
16	//   - names are case-sensitive and surrounding whitespace is kept verbatim;
17	//   - every name's RAW string literal must decode faithfully: bytes that are
18	//     not valid UTF-8, or a \u escape forming an unpaired surrogate (a lone
19	//     high or low surrogate, or a low surrogate before its high surrogate),
20	//     reject the whole document — the decoder's U+FFFD rewrite is never kept
21	//     and the offending node or edge is never skipped, even when the rewrite
22	//     would collide with a real dataset or match the snapshot's declared
23	//     content identifier; that raw scan is shared by every graph and plan
24	//     reader and lives in name_encoding.go (the graph document scope is in
25	//     graph_name_encoding.go);
26	//   - record order and upstream order are irrelevant, duplicate upstreams count
27	//     as one relationship, and an empty upstream list marks a root, so an
28	//     empty graph stays legal;
29	//   - a known field declared twice within the same object (datasets in the
30	//     graph object, name or upstreams in a dataset record) is rejected,
31	//     however the two declarations are spelled; that JSON-level scan is
32	//     shared by every document reader and lives in duplicate_fields.go.
33	//
34	// The snapshot-only envelope rules (required fields, format version, content
35	// identifier, and duplicates of the snapshot's own fields) live in
36	// snapshot.go; this file is only the common graph structure.
37	package chainledger
38	
39	import (
40		"fmt"
41		"sort"
42		"strings"
43		"unicode/utf8"
44	)
45	
46	// adjacency maps a dataset name to its sorted, duplicate-free parent names.
47	type adjacency map[string][]string
48	
49	// validateInMemoryNamesUTF8 rejects an in-memory graph whose dataset name or
50	// direct upstream reference is not valid UTF-8.
51	//
52	// Such names cannot exist in a file read by the JSON readers (json.Unmarshal
53	// replaces invalid bytes with U+FFFD), but they can exist in a graph built
54	// through Register or by hand. They must never reach an exporter: encoding/json
55	// would silently replace every invalid byte with U+FFFD, so two different
56	// names ("p\xff" and "p\xfe") could serialize identically and a re-read graph
57	// would no longer be a faithful copy. The whole graph is rejected instead.
58	//
59	// Nodes are visited in name byte order and each node's parents in their stored
60	// order, so the first reported name is stable regardless of map iteration.
61	// The offending name is quoted with %q, which keeps the raw bytes readable
62	// ("p\xff" differs from "p\xfe", and a genuinely valid "p�" is shown as
63	// the replacement character itself). The graph is only read, never modified.
64	// Nil lineage nodes are skipped here; the caller rejects those separately.
65	func validateInMemoryNamesUTF8(graph map[string]*Lineage) error {
66		names := make([]string, 0, len(graph))
67		for name := range graph {
68			names = append(names, name)
69		}
70		sort.Strings(names)
71		for _, name := range names {
72			if !utf8.ValidString(name) {
73				return fmt.Errorf("%w: dataset name %q is not valid UTF-8, so the graph cannot be exported faithfully", ErrInvalidArgument, name)
74			}
75			entry := graph[name]
76			if entry == nil {
77				continue
78			}
79			for _, parent := range entry.Parents {
80				if !utf8.ValidString(parent) {
81					return fmt.Errorf("%w: dataset %q references upstream %q whose name is not valid UTF-8", ErrInvalidArgument, name, parent)
82				}
83			}
84		}
85		return nil
86	}
87	
88	// normalizeDatasets builds the normalized parent adjacency from parsed dataset
89	// records. It rejects empty dataset names and datasets declared more than
90	// once; every surviving upstream list is sorted and deduplicated. It does not
91	// check that upstreams resolve to a declared dataset; use
92	// firstMissingReference for that.
93	func normalizeDatasets(datasets []GraphDataset) (adjacency, error) {
94		adj := make(adjacency, len(datasets))
95		for _, ds := range datasets {
96			if ds.Name == "" {
97				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
98			}
99			if _, exists := adj[ds.Name]; exists {
100				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
101			}
102			adj[ds.Name] = uniqueSorted(ds.Upstreams)
103		}
104		return adj, nil
105	}
106	
107	// firstMissingReference is the single authority for the direct-upstream rule,
108	// shared by every graph that gets checked: the graph read from a file, the
109	// graph embedded in a snapshot, a live in-memory graph, and the final graph a
110	// batch converges on. Every direct upstream a dataset names must be a dataset
111	// that exists in the graph being checked; nothing else is judged here (the
112	// cycle rule lives in validateAcyclic).
113	//
114	// Referrers are visited in sorted name byte order and each referrer's parents
115	// in sorted byte order, so the first reported (referrer, upstream) pair is
116	// stable regardless of map iteration, record order, or upstream input order.
117	// Names are compared verbatim — case and surrounding whitespace matter — and
118	// a parent list is expected to already be normalized, so a repeated upstream
119	// is one relationship and can only be reported once. An empty graph or a
120	// dataset with no parents yields ok == false.
121	func firstMissingReference(adj adjacency) (referrer, referenced string, ok bool) {
122		names := make([]string, 0, len(adj))
123		for name := range adj {
124			names = append(names, name)
125		}
126		sort.Strings(names)
127		for _, name := range names {
128			for _, parent := range adj[name] {
129				if _, exists := adj[parent]; !exists {
130					return name, parent, true
131				}
132			}
133		}
134		return "", "", false
135	}
136	
137	// missingReferenceError rejects an existing graph — one read from a file,
138	// embedded in a snapshot, or held in memory — that references a name that is
139	// not a dataset of that graph. The name is described as "not registered", the
140	// wording every existing-graph check has always used; the referrer and the
141	// referenced name are both quoted, and the failure is ErrNotFound so Go callers
142	// can recognize it with errors.Is.
143	func missingReferenceError(referrer, referenced string) error {
144		return fmt.Errorf("%w: dataset %q references upstream %q which is not registered", ErrNotFound, referrer, referenced)
145	}
146	
147	// finalGraphMissingReferenceError rejects a batch whose final graph — the
148	// graph after every add, replacement, and removal — still references a name
149	// that is absent from that final graph. This is the same direct-upstream rule
150	// as missingReferenceError (both run firstMissingReference), but judged on the
151	// final graph and worded for that stage: a dataset newly added in the same
152	// batch may reference another dataset declared later in the plan, while a
153	// retained dataset that still points at a removed name is rejected with no
154	// automatic edge removal or conversion to a root. The referrer and the
155	// referenced name are both quoted, and the failure is ErrNotFound.
156	func finalGraphMissingReferenceError(referrer, referenced string) error {
157		return fmt.Errorf("%w: dataset %q references upstream %q which does not exist in the final graph", ErrNotFound, referrer, referenced)
158	}
159	
160	// validateGraphStructureFromFile runs every graph-structure rule shared by the
161	// file readers: it normalizes the records, rejects empty names, duplicate
162	// datasets, and unregistered upstreams, then rejects cycles. The returned
163	// adjacency is the canonical form of the graph's semantics.
164	func validateGraphStructureFromFile(datasets []GraphDataset) (adjacency, error) {
165		adj, err := normalizeDatasets(datasets)
166		if err != nil {
167			return nil, err
168		}
169		return validateGraphAdjacency(adj)
170	}
171	
172	// validateGraphAdjacency runs the structure rules that apply to an existing
173	// graph after its records have been normalized (empty names and duplicate
174	// declarations already rejected): every direct upstream must be a declared
175	// dataset, and the parent edges must be acyclic. It is the shared tail of both
176	// existing-graph structure authorities, validateGraphStructureFromFile for
177	// parsed documents and validatedGraphAdjacency for live in-memory graphs, so
178	// the two inputs can never disagree about whether one set of direct-upstream
179	// relations is legal. The batch path checks the same direct-upstream rule on
180	// its final graph with firstMissingReference directly; the two stages stay
181	// distinct because an existing graph is rejected before any plan is judged.
182	func validateGraphAdjacency(adj adjacency) (adjacency, error) {
183		if referrer, referenced, missing := firstMissingReference(adj); missing {
184			return nil, missingReferenceError(referrer, referenced)
185		}
186		if err := validateAcyclic(adj); err != nil {
187			return nil, err
188		}
189		return adj, nil
190	}
191	
192	// validateAcyclic reports an error if the parent adjacency contains a cycle
193	// (including a dataset that depends on itself). The error message names the
194	// datasets involved.
195	func validateAcyclic(adj adjacency) error {
196		const (
197			white = 0
198			gray  = 1
199			black = 2
200		)
201		color := make(map[string]int, len(adj))
202		var stack []string
203	
204		var dfs func(node string) error
205		dfs = func(node string) error {
206			color[node] = gray
207			stack = append(stack, node)
208			for _, parent := range adj[node] {
209				switch color[parent] {
210				case gray:
211					// parent is an ancestor of node in the current DFS path, so
212					// following parent edges from parent leads back to parent.
213					idx := 0
214					for stack[idx] != parent {
215						idx++
216					}
217					cycle := make([]string, 0, len(stack)-idx+1)
218					cycle = append(cycle, stack[idx:]...)
219					cycle = append(cycle, parent)
220					return fmt.Errorf("%w: dependency cycle %s", ErrCycle, strings.Join(cycle, " -> "))
221				case white:
222					if err := dfs(parent); err != nil {
223						return err
224					}
225				}
226			}
227			color[node] = black
228			stack = stack[:len(stack)-1]
229			return nil
230		}
231	
232		// Iterate over a sorted snapshot so the first reported cycle is stable
233		// across runs regardless of map iteration order.
234		names := make([]string, 0, len(adj))
235		for name := range adj {
236			names = append(names, name)
237		}
238		sort.Strings(names)
239		for _, name := range names {
240			if color[name] == white {
241				if err := dfs(name); err != nil {
242					return err
243				}
244			}
245		}
246		return nil
247	}
248	
249	// materializeLineage turns validated, normalized parent adjacency into the
250	// in-memory lineage structure every graph reader and every successful batch
251	// leave behind, so both operations follow exactly one relationship rule:
252	//
253	//   - one node exists per adjacency key, carrying an independent copy of its
254	//     sorted, duplicate-free parent list;
255	//   - children are derived in a second pass from the parent edges, so every
256	//     dataset's direct upstreams correspond to those upstreams' direct
257	//     downstreams, with each downstream registered once.
258	//
259	// into is optional: when nil a fresh graph map is allocated and returned
260	// (graph reads); when an existing graph is given (batch applies), nodes absent
261	// from adjacency are deleted and the surviving *Lineage records are reused in
262	// place, so Go callers that already hold the map or a node pointer keep reading
263	// the updated relationships through their own records. Replacing a node's
264	// lists with fresh copies keeps the result independent of adjacency: editing
265	// the plan's final graph or a previously returned report cannot move the
266	// materialized graph.
267	func materializeLineage(into map[string]*Lineage, adj adjacency) map[string]*Lineage {
268		if into == nil {
269			into = make(map[string]*Lineage, len(adj))
270		}
271		// Nodes absent from the adjacency no longer exist; delete them before any
272		// edge is rebuilt, so a removed dataset cannot leave its relationships in
273		// a retained node's lists.
274		for name := range into {
275			if _, ok := adj[name]; !ok {
276				delete(into, name)
277			}
278		}
279		// Install the parent lists first, clearing children. A full rebuild below
280		// derives every child from the parent edges; that wholesale derivation is
281		// what guarantees replaced edges vanish from the old upstream, new
282		// upstreams list the downstream once, and untouched relations survive.
283		for name, parents := range adj {
284			entry := into[name]
285			if entry == nil {
286				entry = &Lineage{}
287				into[name] = entry
288			}
289			entry.Dataset = name
290			entry.Parents = append([]string(nil), parents...)
291			entry.Children = nil
292		}
293		for name, parents := range adj {
294			for _, parent := range parents {
295				into[parent].Children = append(into[parent].Children, name)
296			}
297		}
298		for name := range into {
299			into[name].Children = uniqueSorted(into[name].Children)
300		}
301		return into
302	}
303	
304	// lineageFromAdjacency rebuilds a fresh in-memory graph from validated,
305	// normalized parent adjacency. It is the read path of the shared relationship
306	// rule in materializeLineage; the result is independent of the caller's record
307	// slices.
308	func lineageFromAdjacency(adj adjacency) map[string]*Lineage {
309		return materializeLineage(nil, adj)
310	}
